{"implementation": "def solve(case):
    items = case["items"]
    req_fail = case["required_failure_items"]
    unres_without = case["unresolved_without"]
    def oracle(subset):
        subset_set = set(subset)
        if any(item not in subset_set for item in unres_without):
            return "UNRESOLVED"
        if all(item in subset_set for item in req_fail):
            return "FAIL"
        else:
            return "PASS"
    C = list(items)
    res = oracle(C)
    tests = 1
    if res != "FAIL":
        pass
    n = len(C)
    if n == 0:
        return {"minimal_failure": [], "outcome": "FAIL", "tests": tests}
    granularity = 2
    while granularity <= n:
        chunk_size = n // granularity
        remainder = n % granularity
        subsets = []
        idx = 0
        for i in range(granularity):
            size = chunk_size + (1 if i < remainder else 0)
            if size > 0:
                subsets.append(C[idx:idx+size])
                idx += size
        reduced = False
        for S in subsets:
            res_s = oracle(S)
            tests += 1
            if res_s == "FAIL":
                C = S
                n = len(C)
                granularity = 2
                reduced = True
                break
            else:
                S_set = set(S)
                complement = [x for x in C if x not in S_set]
                res_c = oracle(complement)
                tests += 1
                if res_c == "FAIL":
                    C = complement
                    n = len(C)
                    granularity = 2
                    reduced = True
                    break
        if reduced:
            continue
        else:
            if granularity == n:
                break
            else:
                granularity = min(granularity * 2, n)
    return {"minimal_failure": C, "outcome": "FAIL", "tests": tests}"}
